import heapq


class Solution:
    def mergeKLists(self, lists):
        h = []
        for i, head in enumerate(lists):
            if head:
                heapq.heappush(h, (head.val, i, head))
        dummy = t = ListNode()
        while h:
            v, i, node = heapq.heappop(h)
            t.next = node
            t = t.next
            if node.next:
                heapq.heappush(h, (node.next.val, i, node.next))
        return dummy.next

