class _Node:
    __slots__ = ("key", "val", "prev", "next")

    def __init__(self, k=0, v=0):
        self.key, self.val = k, v
        self.prev = self.next = None


class LRUCache:
    def __init__(self, capacity):
        self.cap = capacity
        self.map = {}
        self.head, self.tail = _Node(), _Node()
        self.head.next = self.tail
        self.tail.prev = self.head

    def _add(self, n):
        n.prev = self.head
        n.next = self.head.next
        self.head.next.prev = n
        self.head.next = n

    def _remove(self, n):
        n.prev.next = n.next
        n.next.prev = n.prev

    def get(self, key):
        if key not in self.map:
            return -1
        n = self.map[key]
        self._remove(n)
        self._add(n)
        return n.val

    def put(self, key, value):
        if key in self.map:
            n = self.map[key]
            n.val = value
            self._remove(n)
            self._add(n)
            return
        if len(self.map) >= self.cap:
            lru = self.tail.prev
            self._remove(lru)
            del self.map[lru.key]
        n = _Node(key, value)
        self._add(n)
        self.map[key] = n

def main():
    cap = int(input())
    q = int(input())
    cache = LRUCache(cap)
    out = []
    for _ in range(q):
        op = input().split()
        if op[0] == "put":
            cache.put(int(op[1]), int(op[2]))
        else:
            out.append(str(cache.get(int(op[1]))))
    print(*out)


